"""Compact explanations for every explicitly configured source parameter."""

GRPO = {
'output_dir':('Checkpoint destination. The lab uses a separate folder per experiment.','Wrong path can mix runs or overwrite files; omitting loses the intended location.'),
'model_init_kwargs':('BF16 model weights reduce memory; SDPA uses optimized attention.','FP32 roughly doubles weight memory; unsupported dtype/kernel fails or falls back. Lab also pins revision.'),
'learning_rate':('2e-5 is the author’s LoRA update scale, a starting hypothesis rather than a proven optimum.','Too high destabilizes KL/reward; too low barely changes behavior. Removing selects TRL’s lower default.'),
'max_steps':('2000 optimizer updates define the budget and linear scheduler horizon.','Positive value overrides num_train_epochs. Removing changes run length; changing on resume changes the schedule.'),
'lr_scheduler_type':('Linear decay reduces the update scale as the budget is spent.','Constant LR keeps moving at the initial scale; mismatched horizon can decay too early.'),
'num_train_epochs':('1 is present in the source but is overridden by positive max_steps.','It only controls duration when max_steps is not positive; this run revisits data.'),
'logging_steps':('1 emits metrics after every optimizer step for diagnosis.','Larger values hide short failures; frequent logging adds a little CPU/I/O overhead.'),
'eval_strategy':('Evaluate periodically on the held-out 10%.','Setting no removes generalization feedback; evaluating too often increases wall time.'),
'eval_steps':('10 updates between held-out checks balances feedback and generation cost.','Too sparse delays detection of overfitting; too frequent spends most time evaluating.'),
'eval_on_start':('Measure the untrained policy before the first update. The lab also saves a separate Baseline.','Without it train() starts without a reference score; the saved baseline still provides one.'),
'per_device_eval_batch_size':('100 sampled completions per device per evaluation batch in the source.','Large evaluation batches need KV/activation memory and can OOM; smaller is slower but valid with G_eval=1.'),
'num_generations_eval':('1 sampled completion per held-out prompt estimates sampled solve rate.','It is not best-of-16 or greedy accuracy. More generations cost more and alter the estimator.'),
'disable_tqdm':('True keeps terminal logs readable alongside custom callbacks.','False restores progress bars; it does not change learning.'),
'per_device_train_batch_size':('16 completion sequences per device per microbatch, not 16 distinct prompts.','Larger uses more activation memory; batch × accumulation must be divisible by G on this one-GPU worker.'),
'gradient_accumulation_steps':('2 microbatches per optimizer update: effective batch=32 completion sequences.','Removing selects 1: only one distinct prompt per update with G=16; changing affects noise, time and grouping.'),
'num_generations':('G=16 candidate completions per prompt supply the within-prompt baseline.','G=1 has no relative reward signal and is invalid for training; larger G trades prompt diversity for exploration.'),
'gradient_checkpointing':('False avoids recomputing forward activations on the large GPU used by the source.','True saves activation memory by recomputation, slowing forward/backward. The classroom preset enables it.'),
'bf16':('True enables BF16 training computation with a wide exponent range.','Requires compatible CUDA hardware. This is separate from the model weight-loading dtype.'),
'max_completion_length':('1024 newly generated tokens cap reasoning cost and KV-cache growth.','Too short clips closing tags/answers and gives zero rewards; too long spends memory/time on rambling.'),
'temperature':('1.0 samples diverse outputs without rescaling logits.','Near zero reduces exploration and can produce equal rewards within every group; very high produces noise.'),
'use_vllm':('True moves rollout generation to a specialized inference engine.','False uses Transformers generation, usually slower but simpler and avoids a second engine’s memory.'),
'vllm_mode':('colocate puts training and generation on the same GPU, avoiding a separate inference server.','Server mode needs a configured reachable server and separate GPU resources; it is not a drop-in flag change.'),
'vllm_gpu_memory_utilization':('0.3 budgets memory for vLLM’s model/KV cache on the shared device.','It does not cap total training VRAM. Too high crowds out training; too low prevents engine startup/cache allocation.'),
'vllm_max_model_length':('1280 = 256 prompt + 1024 completion tokens limits inference context/KV planning.','Below the combined limit can reject/truncate requests; needlessly high consumes capacity or fails engine setup.'),
'beta':('0.001 weights the reference-policy KL regularizer; small relative to the reward term.','0 removes reference KL and its computation; too large prevents learning; too small allows drift. Tune empirically.'),
'save_total_limit':('Keep one rotating optimizer checkpoint to bound disk use.','Removing can fill disk; keeping one means earlier checkpoints cannot be selected later. Lab preserves baseline/final JSON separately.'),
'report_to':('none disables external tracking integrations; custom callbacks still receive metrics.','Removing may activate installed integrations/defaults. It does not disable the notebook’s JSONL charts.'),
}

LORA = {
'r':('16 is the low-rank dimension in ΔW=(α/r)BA.','Lower uses fewer parameters but less capacity; higher costs optimizer memory and may overfit.'),
'lora_alpha':('32 gives the conventional α/r scale of 2 at rank 16.','Changing alpha changes update magnitude even at the same LR; removing selects PEFT’s default.'),
'lora_dropout':('0.05 drops some adapter inputs during training as regularization.','0 removes that regularizer; too high weakens learning. It is disabled during evaluation.'),
'target_modules':('Attention q/k/v/o and MLP gate/up/down projections all receive adapters.','Missing names can fail matching; fewer targets reduce capacity/optimizer state. Removing the entire PEFT config trains all weights.'),
'task_type':('CAUSAL_LM wraps the model for autoregressive next-token generation.','Wrong task can select an incompatible wrapper; this is not a classification head.'),
}

